const body = $json.body ?? $json;
const rawEmail = body.email ?? body;
const candidates = Array.isArray(body.candidates) ? body.candidates : [];
const subject = String(rawEmail.subject ?? '').trim();
const emailBody = String(rawEmail.body ?? rawEmail.text ?? '').trim();
if (!subject && !emailBody) throw new Error('BUYFLOW_EMPTY_EMAIL');
const requestId = String(body.request_id ?? `local-${Date.now()}-${Math.random().toString(16).slice(2)}`);
return [{ json: { request_id: requestId, email: { from: String(rawEmail.from ?? ''), subject, body: emailBody, received_at: rawEmail.received_at ?? null }, candidates: candidates.map((c) => ({ purchase_id: String(c.purchase_id ?? c.id ?? ''), merchant: c.merchant ?? null, order_ids: Array.isArray(c.order_ids) ? c.order_ids : [], tracking_ids: Array.isArray(c.tracking_ids) ? c.tracking_ids : [], invoice_ids: Array.isArray(c.invoice_ids) ? c.invoice_ids : [], amount: c.amount ?? null, currency: c.currency ?? null, created_at: c.created_at ?? null, status: c.status ?? null })).filter((c) => c.purchase_id), mode: 'SHADOW' } }];

const raw = String($json.message?.content ?? $json.response ?? '').trim();
if (!raw) throw new Error('BUYFLOW_OLLAMA_EMPTY_RESPONSE');
let parsed;
try { parsed = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim()); } catch (e) { throw new Error(`BUYFLOW_INVALID_AI_JSON: ${raw.slice(0, 500)}`); }
const events = new Set(['ORDER_CREATED','ORDER_PROCESSING','ORDER_PACKING','SHIPMENT_CREATED','SHIPPED','IN_TRANSIT','OUT_FOR_DELIVERY','READY_FOR_PICKUP','DELIVERED','DELIVERY_FAILED','DELAYED','CANCELLED','REFUNDED','PAYMENT','INVOICE','RETURN','WARRANTY','OTHER']);
const actions = new Set(['CREATE_PURCHASE','LINK_EXISTING','REVIEW','IGNORE']);
if (!events.has(parsed.event_type)) throw new Error(`BUYFLOW_INVALID_EVENT:${parsed.event_type}`);
if (!actions.has(parsed.action)) throw new Error(`BUYFLOW_INVALID_ACTION:${parsed.action}`);
const expectedCommerce = parsed.event_type !== 'OTHER';
if (Boolean(parsed.is_commerce) !== expectedCommerce) throw new Error('BUYFLOW_COMMERCE_INVARIANT_FAIL');
const confidence = Number(parsed.confidence);
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error('BUYFLOW_INVALID_CONFIDENCE');
const original = $('Normalize Request').item.json;
const candidateIds = new Set((original.candidates || []).map((c) => String(c.purchase_id)));
if (parsed.action === 'LINK_EXISTING') { const selected = String(parsed.selected_purchase_id ?? ''); if (!selected || !candidateIds.has(selected)) throw new Error(`BUYFLOW_AI_INVENTED_OR_INVALID_PURCHASE_ID:${selected}`); parsed.selected_purchase_id = selected; } else { parsed.selected_purchase_id = null; }
return [{ json: { ok: true, request_id: original.request_id, provider: 'ollama-local', model: $env.BUYFLOW_OLLAMA_MODEL || 'qwen3:8b', mode: 'SHADOW', execution_allowed: String($env.BUYFLOW_AI_EXECUTE || 'false').toLowerCase() === 'true', decision: { is_commerce: expectedCommerce, event_type: parsed.event_type, action: parsed.action, selected_purchase_id: parsed.selected_purchase_id, confidence, evidence: Array.isArray(parsed.evidence) ? parsed.evidence.slice(0, 8).map(String) : [], reason: String(parsed.reason ?? '').slice(0, 1000) } } }];
